#[allow(unused_variables)]
fn len_0(p: *const u8) -> usize {
    unsafe { (2*16) as usize }
}
#[allow(unused_variables)]
fn len_1(p: *const u8) -> usize {
    unsafe { (2*16) as usize }
}
#[allow(unused_variables)]
fn len_2(p: *const u8) -> usize {
    unsafe { (((*(p as *const VkPipelineMultisampleStateCreateInfo)).rasterizationSamples as usize + 31) / 32) as usize }
}
#[allow(unused_variables)]
fn len_3(p: *const u8) -> usize {
    unsafe { ((*(p as *const VkShaderModuleCreateInfo)).codeSize as usize / 4) as usize }
}
#[allow(unused_variables)]
fn len_4(a: &[*const c_void]) -> usize {
    unsafe { (((*(a[1] as *const VkSampleCountFlagBits)) as usize + 31) / 32) as usize }
}

